+  try {
+    accessSync(e, constants.R_OK);
+    return statSync(e).isFile();
+  } catch {
+    return false;
+  }
+}
+function stageZeroEnvironment(e = {}) {
+  e = {
+    ...process.env,
+    ...e
+  };
